window.docContents[219].resolve({"/2___-Basic-notions-of-representation-theory/2___12___-The-tensor-algebra/Section-2___12___-The-tensor-algebra-___-heading-and-introduction/#Chapter2___Discussion_2___12_heading___heading-1":{"contents":"The notion of tensor product allows us to give more conceptual (i.e., coordinate-free) definitions of the free algebra, polynomial algebra, exterior algebra, and universal enveloping algebra of a Lie algebra.\n\nNamely, given a vector space V, define its tensor algebra TV over a field k to be TV = \\bigoplus_{n \\geq 0} V^{\\otimes n}, with multiplication defined by a \\cdot b := a \\otimes b, a \\in V^{\\otimes n}, b \\in V^{\\otimes m}. Observe that a choice of a basis\n\n","context":"Introduction to Representation Theory\t2. Basic notions of representation theory\t2.12. The tensor algebra\tSection 2.12: The tensor algebra — heading and introduction","header":"2.12. The tensor algebra","id":"/2___-Basic-notions-of-representation-theory/2___12___-The-tensor-algebra/Section-2___12___-The-tensor-algebra-___-heading-and-introduction/#Chapter2___Discussion_2___12_heading___heading-1"},"/4___-Representations-of-finite-groups___-Basic-results/4___5___-Orthogonality-of-characters/Section-4___5___-Orthogonality-of-characters-___-Hermitian-inner-product-on-class-functions/#Chapter4___Introduction_4___5___heading-1":{"contents":"We define a positive definite Hermitian inner product on \\mathrm{F}_c(G, \\mathbb{C}) (the space of central functions) by\n\n(f_1, f_2) = \\frac{1}{|G|} \\sum_{g \\in G} f_1(g)\\overline{f_2(g)}.\nThe following theorem says that characters of irreducible representations of G form an orthonormal basis of F_c(G, \\mathbb{C}) under this inner product.\n\n","context":"Introduction to Representation Theory\t4. Representations of finite groups: Basic results\t4.5. Orthogonality of characters\tSection 4.5: Orthogonality of characters — Hermitian inner product on class functions","header":"4.5. Orthogonality of characters","id":"/4___-Representations-of-finite-groups___-Basic-results/4___5___-Orthogonality-of-characters/Section-4___5___-Orthogonality-of-characters-___-Hermitian-inner-product-on-class-functions/#Chapter4___Introduction_4___5___heading-1"},"/7___-Introduction-to-categories/7___4___-Equivalence-of-categories/Section-7___4___-Equivalence-of-categories/#Introduction-to-Representation-Theory--7___-Introduction-to-categories--7___4___-Equivalence-of-categories--Section-7___4___-Equivalence-of-categories":{"contents":"\n\n","context":"Introduction to Representation Theory\t7. Introduction to categories\t7.4. Equivalence of categories","header":"Section 7.4: Equivalence of categories","id":"/7___-Introduction-to-categories/7___4___-Equivalence-of-categories/Section-7___4___-Equivalence-of-categories/#Introduction-to-Representation-Theory--7___-Introduction-to-categories--7___4___-Equivalence-of-categories--Section-7___4___-Equivalence-of-categories"}});
